#!/usr/bin/env python3
"""lichen backup file vectors (docs/spec/backup.md, ADR-0037).

An independent oracle: the AEAD (RFC 8439, written from the RFC and checked against its test
vectors) and HKDF are frames.py's, loaded from its path; nothing is shared with the Rust code.
Regenerate with:
    python3 -I testdata/lichen/backup.py > testdata/lichen/backup.toml
"""
import hashlib
import importlib.util
import struct
from pathlib import Path

_spec = importlib.util.spec_from_file_location("frames", Path(__file__).with_name("frames.py"))
frames = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(frames)

MAGIC = b"lichen/backup"
VERSION = 1
CHUNK = 65536
END, DATABASE, FILE, SETTINGS = 0, 1, 2, 3


def keys(seed: bytes, salt: bytes):
    key = frames.hkdf(salt, seed, b"lichen/1 backup key")
    check = frames.hkdf(salt, seed, b"lichen/1 backup check")[:16]
    return key, check


def header(seed: bytes, salt: bytes) -> bytes:
    return MAGIC + bytes([VERSION]) + salt + keys(seed, salt)[1]


def entry(kind: int, name: bytes, data: bytes) -> bytes:
    return bytes([kind, len(name)]) + name + struct.pack("<Q", len(data)) + data


def contents(entries) -> bytes:
    return b"".join(entry(k, n, d) for k, n, d in entries) + entry(END, b"", b"")


def seal_file(seed: bytes, salt: bytes, plain: bytes) -> bytes:
    key, _ = keys(seed, salt)
    h = header(seed, salt)
    chunks = [plain[i:i + CHUNK] for i in range(0, len(plain), CHUNK)] or [b""]
    out = h
    for i, c in enumerate(chunks):
        last = i == len(chunks) - 1
        nonce = struct.pack("<Q", i) + bytes([1 if last else 0]) + bytes(3)
        ct, tag = frames.seal(key, nonce, h, c)
        out += ct + tag
    return out


def pattern(n: int, k: int) -> bytes:
    """Large entries are described, not printed: byte i is (31 i + k) mod 251."""
    return bytes((31 * i + k) % 251 for i in range(n))


def show(v) -> str:
    if isinstance(v, bytes):
        return '"' + v.hex() + '"'
    if isinstance(v, str):
        return '"' + v + '"'
    return str(v)


def table(kind: str, **fields):
    print(f"[[{kind}]]")
    for k, v in fields.items():
        print(f"{k} = {show(v)}")
    print()


def main():
    frames.self_check()
    print("# lichen backup vectors (docs/spec/backup.md). Generated by backup.py: do not edit.\n")
    seed = bytes(range(32))
    salt = bytes(range(0x40, 0x60))
    key, check = keys(seed, salt)

    # A whole small file: one chunk, every kind of entry.
    photo = "9f" * 32 + ".jpg"
    settings = b'{"lichen.myName":"Camille","lichen.tor":true}'
    small = [(DATABASE, b"", b"a lichen store"), (FILE, photo.encode(), b"\xff\xd8\xff\xe0 photo"),
             (SETTINGS, b"", settings)]
    plain = contents(small)
    table("small", seed=seed, salt=salt, key=key, check=check, header=header(seed, salt),
          database=small[0][2], file_name=photo, file=small[1][2], settings=settings,
          contents=plain, file_bytes=seal_file(seed, salt, plain))

    # Large files, described by their entry sizes (pattern above): contents of exactly two full
    # chunks (the last one full, no empty chunk after it), then three chunks with a short last.
    for name, db, extra in (("two_full_chunks", 2 * CHUNK - 20, 0), ("three_chunks", 70_000, 65_000)):
        entries = [(DATABASE, b"", pattern(db, DATABASE))]
        if extra:
            entries.append((FILE, photo.encode(), pattern(extra, FILE)))
        plain = contents(entries)
        out = seal_file(seed, salt, plain)
        last = len(header(seed, salt)) + (len(plain) - 1) // CHUNK * (CHUNK + 16)
        table("large", name=name, seed=seed, salt=salt, database_len=db, file_name=photo,
              file_len=extra, contents_len=len(plain), file_len_total=len(out),
              sha256=hashlib.sha256(out).digest(), last_chunk_start=last)


if __name__ == "__main__":
    main()
